private CompletableFuture<WebSocket> ownBuild(final CompletableFuture<WebSocket> built, final long generation) {
  built.whenComplete((webSocket, _) -> {
    if (webSocket != null) {
      final boolean stale;
      lock.lock();
      try {
        stale = closed() || generation != this.connectGeneration;
      } finally {
        lock.unlock();
      }
      if (stale) {
        webSocket.abort();
      }
    }
  });
  return built;
}

