static void signInOrder(final SequencedCollection<Signer> signers,
                        final byte[] out,
                        final int msgOffset,
                        final int msgLen,
                        int sigOffset) {
  for (final var signer : signers) {
    sigOffset = signer.sign(out, msgOffset, msgLen, sigOffset);
  }
}

